{
  "claims": [
    {
      "id": "C1",
      "text": "Whenever we execute a Java program, the main function gets called, and the code inside this function gets executed.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0001", "Q0002"],
      "related_refs": []
    },
    {
      "id": "C2",
      "text": "Functions (methods) should always belong to a class.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0005", "Q0006"],
      "related_refs": []
    },
    {
      "id": "C3",
      "text": "A class is a container for one or more related functions.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0007", "Q0008", "Q0009"],
      "related_refs": []
    },
    {
      "id": "C4",
      "text": "Classes are used to organize our code, similar to how products are organized in a supermarket.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0010", "Q0011", "Q0012", "Q0013", "Q0014"],
      "related_refs": []
    },
    {
      "id": "C5",
      "text": "Every Java program should have at least one class that contains the main function.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0017", "Q0018"],
      "related_refs": []
    },
    {
      "id": "C6",
      "text": "The class that contains the main function is typically named Main.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0019", "Q0020"],
      "related_refs": []
    },
    {
      "id": "C7",
      "text": "To define a class in Java, start with the class keyword, give it a descriptive name, and enclose its body in curly braces.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0022", "Q0023", "Q0024"],
      "related_refs": []
    },
    {
      "id": "C8",
      "text": "Methods defined inside a class are called methods.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0027"],
      "related_refs": []
    },
    {
      "id": "C9",
      "text": "The main function is the entry point of a Java program.",
      "basis": "explicit",
      "availability": "SOURCE_SUPPORTED",
      "literal_kind": "verbal",
      "instructional_role": null,
      "refs": ["Q0025", "Q0026"],
      "related_refs": []
    }
  ],
